xql_query:
// ============================================================
// Rule: WIN_AD Multiple User Creations
// Vendor: Windows
// Objective:
// Detect activity associated with WIN_AD Multiple User Creations.
// Severity: SEV_040_HIGH
// Category: CREDENTIAL_ACCESS
// ============================================================
// SANITIZED: Environment-specific values replaced with generic placeholders.
// MITRE ATT&CK:
// Tactic: TA0003 - Persistence
// Technique: T1136 - Create Account

// Configuração inicial: comparações não diferenciam maiúsculas/minúsculas
// Objetivo: padronizar comparações e evitar perda de eventos por variações de caixa
config case_sensitive = false

// Fonte de dados: telemetria do agente (inclui Windows Security Event Log)
| dataset = xdr_data

// Filtro: garante que estamos analisando apenas eventos de Windows Event Log
// Event ID 4720 = "A user account was created" (criação de conta no AD/Windows)
| filter event_type = ENUM.EVENT_LOG
| filter action_evtlog_event_id = 4720

// Extração/normalização de campos do evento 4720 (Security)
// Observação: os nomes dentro de action_evtlog_data_fields podem variar conforme parsing do tenant.
| alter
    TargetUserName   = action_evtlog_data_fields -> TargetUserName,    // Usuário criado (display/target)
    SamAccountName   = action_evtlog_data_fields -> SamAccountName,    // sAMAccountName do usuário criado
    TargetDomainName = action_evtlog_data_fields -> TargetDomainName,  // Domínio onde a conta foi criada
    Endpoint         = action_evtlog_data_fields -> SubjectUserName    // Executor (quem criou)

// Agrupamento temporal: consolida eventos em janelas de 1 hora para identificar criação em massa
| bin _time span = 1h

// Agregação: contabiliza quantas contas distintas foram criadas na janela
// - users_created: quantidade de usuários distintos criados na janela
// - created_users: lista dos usuários criados (evidência)
| comp
    count_distinct(TargetUserName) as users_created,
    values(TargetUserName) as created_users
  by _time, agent_hostname, Endpoint, TargetDomainName

// Threshold: dispara quando houver criação em massa (ajuste conforme baseline do ambiente)
| filter users_created >= 5

// Ordena para destacar os casos mais críticos
| sort desc users_created

// Saída final: retorna todos os campos disponíveis (útil para troubleshooting)
// Para uso em alerta, é comum substituir por um fields explícito com os campos essenciais.
| fields *

// Execção para criação de usuários locais em workstation.
| filter (`created_users` not contains """lenovo""") 

// Execção para criação de usuários vindas do Sailpoint
| filter Endpoint != "<IDENTITY_PROVISIONING_ACCOUNT>"
